SELECT ?director ?directorIndustry ?korda ?kordaIndustry WHERE {
  ?film wdt:P31 wd:Q11424;                   # film instance
        rdfs:label "Little Children"@en;     # film named Little Children
        wdt:P577 ?releaseDate;                # release date
        wdt:P57 ?director.                    # has director

  FILTER(YEAR(?releaseDate) = 2006)

  ?director wdt:P106 ?directorOccupation.
  ?directorOccupation wdt:P279* ?mediaIndustryClass.

  VALUES ?mediaIndustryClass {
    wd:Q24979    # media industry
    wd:Q10800557 # film director, etc (any suitable subclass or occupation)
  }

  ?korda wdt:P31 wd:Q5;                      # human
         rdfs:label "Zoltan Korda"@en;
         wdt:P106 ?kordaOccupation.

  ?kordaOccupation wdt:P279* ?mediaIndustryClass.

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

LIMIT 10

