}

LIMIT 10

SELECT composer_name FROM FilmScores WHERE film_title = "Veyyil";

SELECT film_title FROM Films WHERE actor_name = "Ashrita Shetty";

SELECT composer_name FROM FilmScores WHERE film_title IN (
    SELECT film_title FROM Films WHERE actor_name = "Ashrita Shetty"
);

SELECT MIN(release_year), film_title FROM FilmScores WHERE composer_name = (
    SELECT composer_name FROM FilmScores WHERE film_title = "Veyyil"
) GROUP BY composer_name;

SELECT 
  (SELECT COUNT(*) FROM campuses WHERE university = 
      (SELECT university_name FROM professors WHERE name = 'Richard J. Wood' AND state = 'Connecticut')
  ) AS ct_university_campuses,
  (SELECT COUNT(*) FROM campuses WHERE university = 'California State Polytechnic University, Pomona') AS cal_poly_pomona_campuses;
